import{_ as o,o as t,c as d,a5 as r}from"./chunks/framework.DSg0KOwT.js";const u=JSON.parse('{"title":"State and History Server intake","description":"","frontmatter":{},"headers":[],"relativePath":"contributor-guide/architecture/state-and-history.md","filePath":"contributor-guide/architecture/state-and-history.md"}'),s={name:"contributor-guide/architecture/state-and-history.md"};function a(c,e,n,i,l,h){return t(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="state-and-history-server-intake" tabindex="-1">State and History Server intake <a class="header-anchor" href="#state-and-history-server-intake" aria-label="Permalink to &quot;State and History Server intake&quot;">​</a></h1><h2 id="state-model" tabindex="-1">State model <a class="header-anchor" href="#state-model" aria-label="Permalink to &quot;State model&quot;">​</a></h2><p><code>src/store/store.ts</code> is a single Zustand store (<code>createStore</code> from <code>zustand/vanilla</code>, wrapped by a <code>useStore</code> hook). It holds all shared state; no component keeps a <code>useState</code> of its own for anything shared. Run state: <code>appModel: AppModel</code>, <code>catalog: Finding[]</code>, <code>configFindings: Finding[]</code>, <code>interpretation</code> (see <a href="#run-interpretation">Run interpretation</a>), <code>taskDataCache</code>, <code>skippedLines</code> (malformed-JSON-line count from the parser&#39;s <code>done</code> payload). File and parse state: <code>activeFileId</code>, <code>sessionCache</code> (in-memory snapshot cache for instant file-switching, see <code>packages/core/src/session-snapshot.ts</code>), <code>parse: {pct, lines, etaMs}</code>, <code>status: &#39;idle&#39;|&#39;parsing&#39;|&#39;ready&#39;|&#39;error&#39;</code>, <code>shsParsing</code>, <code>errorMessage</code>, <code>errorNonce</code>. View state: <code>theme</code>, <code>widgetDensity</code>, <code>comparison</code>/<code>compareLoad</code>/<code>compareSeed</code>, <code>planGraph</code>. Export-only: <code>exportMode</code> and <code>exportProvenance</code>, both set by <code>src/export/hydrate-store.ts</code>.</p><p><code>src/store/useIngest.ts</code> is the only writer during a parse. It builds <code>createModelCallbacks</code>&#39; <code>onProgress</code>/<code>onDone</code>/<code>onError</code> handlers to call the store&#39;s setters directly (<code>setParse</code>, <code>setFindings</code>, <code>setStatus</code>, <code>setSkippedLines</code>, <code>setTaskData</code>, ...). Components never talk to the worker: they use <code>useIngest()</code>&#39;s returned actions (<code>startLoad</code>/<code>startLoadFolder</code>/<code>startLoadFromUrl</code>/<code>pickRecent</code>/<code>getTaskData</code>/ <code>resetToDropZone</code>/<code>cancelParse</code>, plus the comparison actions <code>prepareComparison</code>/<code>startCompareLoad</code>/<code>compareWithAnotherRun</code>/<code>drillIntoRun</code>) and the store&#39;s read state. <code>resetToDropZone</code> snapshots the current run into <code>sessionCache</code> before resetting; <code>cancelParse</code> (the parse screen&#39;s <strong>Cancel</strong>) terminates the worker and never snapshots, so a half-parsed model with no findings can&#39;t be restored later.</p><p><code>resetModel()</code> empties the run state (<code>appModel</code>, <code>catalog</code>, <code>configFindings</code>, <code>interpretation</code>, <code>taskDataCache</code>, <code>skippedLines</code>), returns <code>status</code> to idle, clears <code>shsParsing</code> and <code>errorMessage</code>, closes any comparison or plan-graph view, and bumps <code>modelResetCount</code>. It runs on every new parse, reset-to-drop-zone, cancelled parse, typed SHS failure and compare-load parse. That counter has no setter of its own; only <code>PlanGraphRoute.tsx</code>&#39;s <code>store.subscribe</code> reads it, to evict the plan-graph model memo cache (see <a href="./drill-down/plan-graph.html#plan-graph-view">Plan graph view</a>).</p><h3 id="run-interpretation" tabindex="-1">Run interpretation <a class="header-anchor" href="#run-interpretation" aria-label="Permalink to &quot;Run interpretation&quot;">​</a></h3><p>The rule: whatever states a conclusion about this run is computed once by the producer, whatever responds to what the viewer does is computed live.</p><p><code>interpretRun</code> (<code>packages/core/src/run-interpretation.ts</code>) is that one computation; its <code>RunInterpretation</code> interface lists what it returns (verdict and next steps, which checks could not run and why, formatted savings and their rank, the Scorecard figures and flags, per-stage finding order, the Findings board&#39;s rollup, and per finding type the widget order, doc anchor and clean-check criterion). It refers to findings by index into <code>[...catalog, ...configFindings]</code>, so a renderer resolves them to the objects it already holds and reference-identity routing keeps working.</p><p>The store&#39;s <code>interpretation</code> holds that result with the findings it indexes. The live app fills it from <code>src/store/live-interpretation.ts</code>, a <code>store.subscribe</code> installed by <code>src/main.tsx</code> (and <code>tests/view/setup.ts</code>) that reinterprets whenever <code>appModel</code>, <code>catalog</code> or <code>configFindings</code> changes. Widgets read it through <code>src/view/interpretation.ts</code>. What stays live responds to the viewer: filtering, sorting and expanding; the Findings board regrouped over the findings a filter keeps (<code>boardRollup</code>: unfiltered, it renders the carried groups as is; a time group&#39;s recoverable figure is capped by the union of its members&#39; stage intervals, so a filtered subset cannot be re-totalled from the carried per-group numbers); and the Scaling Simulator&#39;s <code>simulateScaling</code>, a what-if the viewer drives. A widget test that renders one widget with findings as props installs an interpretation first with <code>tests/view/_shared/interpretation.ts</code>.</p><p>Some view judgments sit outside the rule. StageTable&#39;s RETRY, fetch-wait, spill and I/O-ratio chips, PlanView&#39;s cross-join, long-filter and exchange-count warnings, and the plan graph&#39;s duration-share heat colours use thresholds in the view code, with no finding behind them. Do not copy that pattern.</p><p>The HTML export carries the same result. <code>buildHtmlExportData</code> (<code>packages/core/src/html-export.ts</code>), shared by the CLI&#39;s <code>--export-html</code> and the dashboard&#39;s download, calls <code>interpretRun</code> and writes it into the payload (<code>EXPORT_DATA_SCHEMA_VERSION</code> 3) with a provenance stamp: core version, core build id (<code>coreSourceHash</code> of the core sources: <code>coreBuildId</code> in <code>load-vendored.js</code> for the CLI, a Vite <code>define</code> for the web build, see <code>src/build-info.ts</code>) and producer, all shown in the export footer. With redaction on, it redacts the run model and findings first and interprets the redacted copy, so no text derived from a redacted value (a quoted failure reason cut mid-host, say) keeps a fragment of it; the md/json report does the same. The export bundle never installs the live interpreter: <code>hydrateExportStore</code> installs the payload&#39;s interpretation as is, and <code>src/export/main-export.tsx</code> refuses, before rendering, any payload whose <code>schemaVersion</code> it was not built for, or that lacks its <code>configFindings</code> or <code>interpretation</code> (<code>unsupportedPayloadReason</code>). An exported file therefore shows the conclusions of the core that wrote it, and cannot be reinterpreted by a later bundle.</p><p>What the bundle may import is checked at build time. <code>vite.export.config.ts</code> resolves the live-only modules to stand-ins in <code>src/export/live-only-stubs/</code> (<code>useIngest</code>, <code>useRecentFiles</code>, <code>EvidenceExport</code>, <code>core-usage-histogram-data</code>), whose controls the exported dashboard hides or replaces with an &quot;isn&#39;t included in exported reports&quot; note. Then <code>exportAnalysisGuard</code> (<code>scripts/export-analysis-guard.mjs</code>) fails the build if the graph from <code>src/export/main-export.tsx</code> reaches a <code>packages/core/</code> module missing from <code>ALLOWED_EXPORT_CORE_MODULES</code>, or any of <code>LIVE_ONLY_MODULES</code>, naming each module and one importer chain back to the entry. <code>tests/export-analysis-guard.test.js</code> runs the real export build (<code>--mode guard</code>) so <code>npm test</code> catches a regression. A new core import off the allowlist fails the build: move its conclusion into <code>interpretRun</code>, or, if it only responds to what the viewer does, add it to the allowlist. The guard checks modules, not code: a threshold written straight into a widget passes it.</p><h3 id="finding-filter-state" tabindex="-1">Finding filter state <a class="header-anchor" href="#finding-filter-state" aria-label="Permalink to &quot;Finding filter state&quot;">​</a></h3><p>The board-wide finding filter (impact band, raw <code>finding.type</code>, stage) lives outside the Zustand store, in <code>FindingFilterContext</code> (<code>src/view/FindingFilterContext.tsx</code>): a <code>createContext</code>+<code>useState</code><code>FilterSelection</code> (<code>src/view/finding-filter.ts</code>, three <code>Set</code>s) that every widget filters <code>catalog</code> through via <code>filterFindings</code>. It is seeded from the URL&#39;s <code>impact</code>/<code>type</code>/<code>stage</code> query params on mount and nowhere else, so a reload with no params gives the unfiltered board. Every change writes those params back with <code>history.replaceState</code>, never <code>push</code>, so filtering doesn&#39;t grow Back history. A <code>popstate</code> listener re-seeds the selection from the URL, so Back and forward re-apply filters.</p><p>Switching files resets the selection to empty, keyed on the stable file id rather than <code>catalog</code>, so a same-file catalog refresh keeps the active filter. A page reload re-reads the address bar, so deep-linked filtered URLs still restore. Filters are seeded only from the URL and never persisted anywhere else (no localStorage, no restore-as-default): a filtered view silently becoming the default on reload would risk hiding findings from a user who didn&#39;t realize a filter was still active, so a plain reload with no filter params is always the unfiltered board.</p><h3 id="recent-files-vs-session-cache" tabindex="-1">Recent files vs. session cache <a class="header-anchor" href="#recent-files-vs-session-cache" aria-label="Permalink to &quot;Recent files vs. session cache&quot;">​</a></h3><p>Two mechanisms cover reopening a file, at different lifetimes.</p><p><code>sessionCache</code> (in the Zustand store, see <a href="#state-model">State model</a>) is in-memory and per-session: it makes switching between files already loaded in the current tab instant, and it is gone on reload.</p><p>Recent files (<code>packages/core/src/recent-files.ts</code>, consumed by <code>src/view/useRecentFiles.ts</code>, <code>DropZone.tsx</code> and <code>useIngest.ts</code>) is IndexedDB-backed and cross-session. It persists each file&#39;s <code>FileSystemFileHandle</code> plus light metadata (name, size, <code>lastModified</code>, app name, issue count, <code>lastOpenedAt</code>), capped at 10 entries with the oldest evicted past the cap, so a file can be reopened after a full browser restart, pending the browser re-granting permission on the handle. Picking a recent entry re-parses from the handle; no parsed model is ever persisted.</p>',19)])])}const g=o(s,[["render",a]]);export{u as __pageData,g as default};
